class Solution {
    public: vector<vector<int>> intervalIntersection(vector<vector<int>>& firstList,vector<vector<int>>& secondList){
        vector<vector<int>> answer;
        int i=0,j=0;
        while(i<(int)firstList.size()&&j<(int)secondList.size()){
            int low=max(firstList[i][0],secondList[j][0]),high=min(firstList[i][1],secondList[j][1]);
            if(low<=high)answer.push_back({
                low,high
            });
            if(firstList[i][1]<secondList[j][1])++i;
            else ++j;
        }
        return answer;
    }
};
